# Code generated by Claude
"""
Measurement only (David, Part 4 step 1, 2026-10-26): the place's OVER stop and the hand's angle. Nothing in src/ and no setting is changed.

    MUJOCO_GL=egl python experiments/place_over_angle_measure.py moved      # the moved layout's chosen spot, where the episode fails
    MUJOCO_GL=egl python experiments/place_over_angle_measure.py normal     # the normal layout's chosen spot, where it succeeds

One layout per process (memory). Phases:
 1. the pipeline's stance selection and one full episode of PLAN4; a source records, at the first tick of the place's OVER, the state, the arm's command, the waypoint target and the skill's
    pad rotation (the hold's pad_rotation: approach along the robot's forward direction, hand level);
 2. the arm's own IK (MinkArm, the skill's solver and settings) from that state on the OVER target with the hand turned around the VERTICAL axis through the beaker's centre by 0, 5, ... 355 degrees
    (the pad centre target turns around the same axis; the beaker stays upright, the tilt is the skill's own): best position error and rotation error, against the episode's waypoint tolerance
    (PICK_PLACE_CFG tol_m and tol_rad);
 3. the full check's side: the same selection with a recording wrapper to get the points the check solved, the full check's IK solution for the "carry" point (the OVER stop) and its hand angle
    next to the skill's, and for every turn of phase 2 the full check's collision tests (arm against the robot, hand and arm clearance to the furniture and the objects) at the solution of phase 2.
Output: docs/reports/logs/place_over_angle_<layout>.json (written to a temporary file, then renamed).
"""
import copy
import gc
import json
import math
import os
import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mink  # noqa: E402
import mujoco  # noqa: E402
import numpy as np  # noqa: E402
from scipy.spatial.transform import Rotation  # noqa: E402

from src.arm_kinematics import batch_fk  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.grasp_rules import _axes  # noqa: E402
from src.mink_arm import MinkArm  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.mpvi_postprocess import postprocess  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BENCH_STANCE_CFG, MINK_CFG, PICK_PLACE_CFG, TASK_CFG  # noqa: E402
from stance_select_moved_test import MOVED  # noqa: E402
from stance_select_test import PLAN4  # noqa: E402

STEP_DEG = 5
MAX_STEPS = 1500


def rz(deg):
    a = math.radians(deg)
    return np.array([[math.cos(a), -math.sin(a), 0.0], [math.sin(a), math.cos(a), 0.0], [0.0, 0.0, 1.0]])


def pose_err(arm, d, target, R):
    p, Rm = arm.pad_pose(d)
    return float(np.linalg.norm(p - target)), float(np.degrees(np.linalg.norm(Rotation.from_matrix(Rm.T @ R).as_rotvec())))


def hand_angles(R_tcp, C):
    """(approach azimuth from the torso's forward axis towards the left, approach elevation, closing-axis elevation), degrees, of tool frame rotations."""
    a, y = _axes(R_tcp, C)
    return (float(np.degrees(np.arctan2(a[..., 1], a[..., 0]))), float(np.degrees(np.arcsin(np.clip(a[..., 2], -1, 1)))), float(np.degrees(np.arcsin(np.clip(y[..., 2], -1, 1)))))


def capture_episode(cfg):
    """Phases 1: the stance selection, the episode, the first OVER tick."""
    task = make_pipeline_task(PLAN4, task_cfg=cfg)
    sel = task["stance_selection"]
    sim = load_task(cfg, cameras=True)
    m, d = sim.model, sim.data
    S = {"first": None, "seen": False, "done": False}

    def src_step(obs):
        ep = obs.get("policy")
        orch = task["pipeline"].get("orchestrator")
        if not ep or not orch or S["done"]:
            return None
        manip = task["pipeline"]["manipulation"]
        if "4/4 PLACE: OVER" not in ep["phase"]:
            if S["seen"]:
                S["done"] = True
            return None
        st = manip["state"]["steps"][manip["state"]["i"]]
        if st["name"] != "OVER" or S["seen"]:
            return None
        S["seen"] = True
        S["first"] = {"t": float(d.time), "qpos": d.qpos.copy(), "qcmd": manip["arm"].q_cmd.copy(), "target": np.asarray(st["target"]).copy(), "R": np.asarray(st["R"]).copy()}
        return None

    s = run_episode(task, m, d, out_dir=PROJECT_ROOT / "data" / "place_over_angle" / "episode", extra_sources=lambda mm, dd: {"over": {"name": "over", "step": src_step}}, stop_after_handoff_s=None)
    return task, sel, S["first"], s["outcome"], m


def main():
    name = sys.argv[1] if len(sys.argv) > 1 else "moved"
    cfg = {"moved": MOVED, "normal": TASK_CFG}[name]
    out = {"layout": name}
    task, sel, first, outcome, m = capture_episode(cfg)
    run = sel["runs"][0]
    out["stance"] = {"xy": [float(v) for v in run["stance"]["xy"]], "q": float(run["stance"]["q"]), "yaw": float(run["stance"]["yaw"])}
    out["episode_outcome"] = str(outcome)
    print(f"[{name}] stance {out['stance']}, episode outcome {outcome}", flush=True)
    if first is None:
        out["error"] = "the place's OVER was not reached"
        _save(name, out)
        return
    out["over_target"] = {"t": first["t"], "target": first["target"].round(4).tolist(), "R_skill_world": first["R"].round(5).tolist()}
    tol_m, tol_rad = PICK_PLACE_CFG["tol_m"], PICK_PLACE_CFG["tol_rad"]
    tol_deg = math.degrees(tol_rad)
    out["tolerance"] = {"mm": 1000 * tol_m, "deg": tol_deg}
    hp_xy = np.asarray(cfg["hotplate_xy"], float)         # the beaker's centre axis at the set-down (the place's destination, TASK_CFG's hotplate)
    # ---- phase 2: the skill's solver, hand turned around the vertical through the beaker's centre
    ids = arm_ids(m, "left")
    qadr = np.asarray(ids["qadr"])
    home_q = np.asarray(cfg["home_q_left"], float)
    turns = []
    for deg in range(0, 360, STEP_DEG):
        Rt = rz(deg) @ first["R"]
        tgt = first["target"].copy()
        tgt[:2] = hp_xy + (rz(deg) @ np.array([*(first["target"][:2] - hp_xy), 0.0]))[:2]
        d2 = mujoco.MjData(m)
        d2.qpos[:] = first["qpos"]
        mujoco.mj_kinematics(m, d2)
        arm = MinkArm(m, d2, "left", home_q, copy.deepcopy(MINK_CFG))
        arm.q_cmd = first["qcmd"].copy()
        best, fail, e = None, None, (9e9, 9e9)
        for k in range(MAX_STEPS):
            try:
                arm.step(d2, tgt, Rt)
            except mink.NoSolutionFound:
                fail = k
                break
            d2.qpos[qadr] = arm.q_cmd
            mujoco.mj_kinematics(m, d2)
            e = pose_err(arm, d2, tgt, Rt)
            if best is None or e[0] + 0.05 * e[1] / 57.3 < best[0] + 0.05 * best[1] / 57.3:
                best = e
            if e[0] < 5e-4 and e[1] < 0.1:
                break
        e = pose_err(arm, d2, tgt, Rt)
        row = {"turn_deg": deg, "pos_err_mm": 1000 * e[0], "rot_err_deg": e[1], "best_pos_mm": None if best is None else 1000 * best[0], "no_solution_at_step": fail, "steps": k + 1,
               "within_tolerance": bool(e[0] <= tol_m and e[1] <= tol_deg), "q": arm.q_cmd.round(5).tolist()}
        turns.append(row)
        print(f"  turn {deg:3d}: {row['pos_err_mm']:.2f} mm {row['rot_err_deg']:.2f} deg {'OK' if row['within_tolerance'] else '--'} ({k + 1} steps)", flush=True)
    out["turns"] = turns
    del m
    gc.collect()
    # ---- phase 3: the full check's side
    from src.full_check import FullCheck
    from src.stance_select import make_context, select_bench_stance
    from src.world_model import StaticTaskSource, WorldModel
    import src.bench_stance as bs
    maps_dir = "data/reach_map"
    maps = bs.load_maps(maps_dir, sides=("left",))
    fc = FullCheck(maps={**bs.load_maps(maps_dir)}, task_cfg=cfg, say=lambda *a: None)
    ctx = make_context(fc.model, fc.scene_data, maps, cfg, BENCH_STANCE_CFG, chk=fc.chk, say=lambda *a: None)
    world = WorldModel([StaticTaskSource(cfg)])
    world.refresh(0.0)

    class Rec:
        def __init__(self):
            self.calls = []

        def check(self, stance, points, *a, **k):
            self.calls.append((tuple(float(v) for v in stance), points))
            return fc.check(stance, points, *a, **k)

    rec = Rec()
    s2 = select_bench_stance(postprocess(PLAN4, False, say=lambda *a: None), world, cfg, ctx, BENCH_STANCE_CFG, full_check=rec, say=lambda *a: None)
    st2 = s2["report"]["runs"][0]["stance"]
    stance = (float(st2["xy"][0]), float(st2["xy"][1]), float(st2["yaw"]), float(st2["q"]))
    out["stance_phase3"] = list(stance)
    points = [c for c in rec.calls if abs(c[0][0] - stance[0]) < 1e-9 and abs(c[0][1] - stance[1]) < 1e-9 and abs(c[0][3] - stance[3]) < 1e-9][0][1]
    ci = [i for i, p in enumerate(points) if p.get("path") == "carry"][0]
    info = fc._solve_stance(stance, points, None)
    out["full_check_solve"] = {"ok": bool(info["ok"]), "failed_point": info["failed_point"], "carry_index": ci, "bins": info["bins"], "carry_point_world": [round(v, 4) for v in points[ci]["p"]]}
    C = fc.C
    th = stance[2]
    Rw2t = rz(-math.degrees(th))
    # the skill's hand rotation in the torso frame as a tool frame rotation (the constraint's convention): R_tcp = R_pad R_pad_in_tcp^T
    gf = C
    R_pad_in_tcp = np.column_stack([gf["closing_axis"], np.cross(gf["approach_axis"], gf["closing_axis"]), gf["approach_axis"]])
    R_skill_tcp = Rw2t @ first["R"] @ R_pad_in_tcp.T
    out["skill_hand_angles_deg"] = dict(zip(("approach_azimuth", "approach_elevation", "closing_axis_elevation"), hand_angles(R_skill_tcp, C)))
    if info["ok"] or not np.isnan(info["solution"][ci]).any():
        Qc = info["solution"][ci][None]
        p, Rf = batch_fk(fc.chain, Qc, fc.pad)
        out["full_check_hand_angles_deg"] = dict(zip(("approach_azimuth", "approach_elevation", "closing_axis_elevation"), hand_angles(Rf[0], C)))
        out["full_check_vs_skill_rotation_deg"] = float(np.degrees(np.linalg.norm(Rotation.from_matrix(Rf[0].T @ R_skill_tcp).as_rotvec())))
        out["full_check_solution_q"] = Qc[0].round(5).tolist()
    # the collision tests of the full check at every turn's solution
    cfg_fc = fc.cfg
    for row in turns:
        Q = np.array([row["q"]])
        coll = bool(fc._checker(stance[3]).check(Q)[0])
        hm, am, hp, ap = fc.clear.arm_distances(stance, Q)
        row["collision_arm_vs_robot"] = coll
        row["hand_clearance_mm"] = 1000 * float(hm[0])
        row["arm_clearance_mm"] = 1000 * float(am[0])
        row["collision_tests_pass"] = bool((not coll) and hm[0] >= cfg_fc["hand_clearance"] and am[0] > cfg_fc["arm_clearance"])
        row["pair_hand"], row["pair_arm"] = hp[0], ap[0]
    out["collision_limits_mm"] = {"hand": 1000 * cfg_fc["hand_clearance"], "arm": 1000 * cfg_fc["arm_clearance"]}
    ok_turns = [r["turn_deg"] for r in turns if r["within_tolerance"] and r["collision_tests_pass"]]
    reach_turns = [r["turn_deg"] for r in turns if r["within_tolerance"]]

    def ranges(vals):
        if not vals:
            return []
        s = sorted(vals)
        runs, cur = [], [s[0]]
        for v in s[1:]:
            if v - cur[-1] == STEP_DEG:
                cur.append(v)
            else:
                runs.append(cur)
                cur = [v]
        runs.append(cur)
        if len(runs) > 1 and runs[0][0] == 0 and runs[-1][-1] == 360 - STEP_DEG:      # wrap around
            runs[0] = runs[-1] + runs[0]
            runs.pop()
        return [[r[0], r[-1]] for r in runs]
    wrap = lambda v: ((v + 180) % 360) - 180
    out["summary"] = {"reachable_turns_deg": reach_turns, "reachable_and_collision_pass_turns_deg": ok_turns, "reachable_ranges": ranges(reach_turns), "working_ranges": ranges(ok_turns),
                      "closest_working_turn_deg": (min(ok_turns, key=lambda v: abs(wrap(v))) if ok_turns else None)}
    print(json.dumps(out["summary"]), flush=True)
    _save(name, out)


def _save(name, out):
    Path("docs/reports/logs").mkdir(parents=True, exist_ok=True)
    tmp = Path(f"docs/reports/logs/place_over_angle_{name}.json.tmp")
    tmp.write_text(json.dumps(out, indent=1, default=str))
    tmp.replace(Path(f"docs/reports/logs/place_over_angle_{name}.json"))


if __name__ == "__main__":
    main()
